B.jQ=new A.ag(58173,"MaterialIcons",null,!1)
B.d0s=new A.dw("Estimativa com os escal\xf5es de IRS de 2026 e 11 % de Seguran\xe7a Social, corrigida pela reten\xe7\xe3o real do seu emprego atual. Valores para orienta\xe7\xe3o; confirme com o recibo da nova empresa.",!1,B.jQ,null)
B.d0t=new A.dw("A taxa de esfor\xe7o passa os 35 %: o banco pode recusar ou pedir mais entrada.",!0,null,null)
B.d0u=new A.aoL("heranca","Heran\xe7a e testamento","O que tem e de quem \xe9: im\xf3veis, contas, seguros, d\xedvidas, e onde est\xe3o os documentos. S\xf3 quem tiver acesso a esta carteira o v\xea.","Detalhes (onde est\xe1, quem \xe9 o titular)",null)
B.d0v=new A.aoL("emergencia","Se me acontecer alguma coisa","Onde est\xe3o as contas, quem contactar e o que fazer primeiro. N\xe3o guarde aqui palavras-passe.","Instru\xe7\xf5es",null)
